#ifdef GL_ES
precision mediump float;
#endif

// ========== SDF PRIMITIVES ========== //
float sphereSDF(vec3 p, float r)
{
    return length(p) - r;
}

// We now have 4 spheres in the scene:
float sceneSDF(vec3 p)
{
    vec3 pos1 = vec3(-2.0, 0.0,  0.0);
    vec3 pos2 = vec3( 0.0, 0.0,  0.0);
    vec3 pos3 = vec3( 2.0, 0.0,  0.0);
    vec3 pos4 = vec3( 0.0, 0.0, -2.0); // our new glass sphere

    float d1 = sphereSDF(p - pos1, 1.0);
    float d2 = sphereSDF(p - pos2, 1.0);
    float d3 = sphereSDF(p - pos3, 1.0);
    float d4 = sphereSDF(p - pos4, 1.0); // distance to the glass sphere

    // Return the smallest distance
    return min(d1, min(d2, min(d3, d4)));
}

float raymarch(vec3 ro, vec3 rd)
{
    const int   STEPS    = 128;
    const float MAX_DIST = 50.0;

    float t = 0.0;
    for(int i = 0; i < STEPS; i++)
    {
        vec3 p = ro + rd * t;
        float distToScene = sceneSDF(p);
        if(distToScene < 0.001)
            return t; // hit
        t += distToScene;
        if(t > MAX_DIST) break; // no hit
    }
    return -1.0; // didn't hit anything
}

vec3 calcNormal(vec3 p)
{
    const float e = 0.0005;
    float dxp = sceneSDF(p + vec3(e,0,0));
    float dxn = sceneSDF(p - vec3(e,0,0));
    float dyp = sceneSDF(p + vec3(0,e,0));
    float dyn = sceneSDF(p - vec3(0,e,0));
    float dzp = sceneSDF(p + vec3(0,0,e));
    float dzn = sceneSDF(p - vec3(0,0,e));
    return normalize(vec3(dxp - dxn, dyp - dyn, dzp - dzn));
}

// ========== GGX HELPER FUNCTIONS ========== //

// Normal Distribution Function
float DistributionGGX(float NdotH, float roughness)
{
    float alpha  = roughness * roughness;
    float alpha2 = alpha * alpha;
    float denom  = (NdotH * NdotH) * (alpha2 - 1.0) + 1.0;
    return alpha2 / (3.14159 * denom * denom);
}

// Geometry
float GeometrySchlickGGX(float NdotV, float roughness)
{
    float r = (roughness + 1.0);
    float k = (r * r) / 8.0;
    return NdotV / (NdotV * (1.0 - k) + k);
}

float GeometrySmith(vec3 N, vec3 V, vec3 L, float roughness)
{
    float NdotV = max(dot(N, V), 0.0);
    float NdotL = max(dot(N, L), 0.0);
    float ggx1  = GeometrySchlickGGX(NdotV, roughness);
    float ggx2  = GeometrySchlickGGX(NdotL, roughness);
    return ggx1 * ggx2;
}

// Fresnel
vec3 FresnelSchlick(float cosTheta, vec3 F0)
{
    return F0 + (1.0 - F0) * pow(1.0 - cosTheta, 5.0);
}

// Combine GGX
vec3 ggxSpecularBRDF(vec3 N, vec3 V, vec3 L, float roughness, vec3 F0)
{
    vec3 H      = normalize(V + L);
    float NdotV = max(dot(N, V), 0.0);
    float NdotL = max(dot(N, L), 0.0);
    float NdotH = max(dot(N, H), 0.0);
    float VdotH = max(dot(V, H), 0.0);

    float D = DistributionGGX(NdotH, roughness);
    vec3  F = FresnelSchlick(VdotH, F0);
    float G = GeometrySmith(N, V, L, roughness);

    float denom = 4.0 * NdotV * NdotL + 0.0001;
    return (D * F * G) / denom;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float camAngle = iTime * 0.2;
    float radius   = 7.0;
    vec3  ro       = vec3(sin(camAngle) * radius, 2.5, cos(camAngle) * radius);
    vec3  target   = vec3(0.0, 0.0, 0.0);

    vec3  cw = normalize(target - ro);  // camera forward
    vec3  up = vec3(0.0, 1.0, 0.0);
    vec3  cu = normalize(cross(cw, up)); // camera right
    vec3  cv = cross(cu, cw);            // actual up

    vec3 rd = normalize(uv.x * cu + uv.y * cv + cw);

    // ------- March --------
    float t = raymarch(ro, rd);
    if(t > 0.0)
    {
        vec3 p = ro + rd * t;     // world pos
        vec3 N = calcNormal(p);   // normal
        vec3 V = normalize(ro - p);

        // Distances to each sphere, to find which we hit
        float d1 = abs(sphereSDF(p - vec3(-2.0, 0.0, 0.0), 1.0));
        float d2 = abs(sphereSDF(p - vec3( 0.0, 0.0, 0.0), 1.0));
        float d3 = abs(sphereSDF(p - vec3( 2.0, 0.0, 0.0), 1.0));
        float d4 = abs(sphereSDF(p - vec3( 0.0, 0.0, -2.0), 1.0));

        //---------------------------------------------------
        // Default material (will be overridden below)
        vec3  baseColor = vec3(1.0);
        float metallic  = 0.0;
        float roughness = 0.5;
        bool  isGlass   = false;

        // Sphere #1: matte red
        if(d1 < d2 && d1 < d3 && d1 < d4)
        {
            baseColor = vec3(1.0, 0.2, 0.2);
            metallic  = 0.0;
            roughness = 0.3;
        }
        // Sphere #2: partly metallic blue
        else if(d2 < d3 && d2 < d4)
        {
            baseColor = vec3(0.2, 0.5, 1.0);
            metallic  = 0.6;
            roughness = 0.2;
        }
        // Sphere #3: mirror
        else if(d3 < d4)
        {
            baseColor = vec3(1.0);
            metallic  = 1.0;
            roughness = 0.0;
        }
        // Sphere #4: glass
        else
        {
            isGlass   = true;
            baseColor = vec3(1.0);  // colorless
            metallic  = 0.0;
            roughness = 0.0;
        }

        //---------------------------------------------------
        // Common Fresnel base
        vec3 F0 = mix(vec3(0.04), baseColor, metallic);

        //---------------------------------------------------
        // Simple direct lighting
        float lightAngle = iTime * 0.6;
        vec3  lightDir   = normalize(vec3(sin(lightAngle)*3.0, 1.0, cos(lightAngle)*3.0));
        float NdotL      = max(dot(N, lightDir), 0.0);

        vec3 diffuse     = (1.0 - metallic) * baseColor / 3.14159;
        vec3 specular    = ggxSpecularBRDF(N, V, lightDir, roughness, F0);
        vec3 direct      = (diffuse + specular) * NdotL;

        //---------------------------------------------------
        // Environment for reflection/refraction
        // (simple lookup from iChannel0)
        vec3 R        = reflect(-V, N); 
        vec3 envColor = texture(iChannel0, R).rgb;

        //---------------------------------------------------
        // If glass, do a simple environment-based refraction
        // (For physically correct refraction, you'd typically 
        //  do an extra ray-march. Here we just sample the 
        //  cubemap.)
        vec3 color;
        if(isGlass)
        {
            float ior         = 1.5;  // index of refraction
            // Refract direction (air -> glass)
            //   incoming is -V, normal is N
            vec3 refrDir      = refract(-V, N, 1.0 / ior);
            vec3 refractColor = texture(iChannel0, refrDir).rgb;

            // Fresnel factor for reflection vs. refraction
            float cosTheta    = max(dot(-V, N), 0.0);
            vec3  F           = FresnelSchlick(cosTheta, vec3(0.04));
            vec3  reflectCol  = texture(iChannel0, R).rgb;

            // Weighted combination of refraction & reflection
            color = mix(refractColor, reflectCol, F);

            // Add a bit of direct lighting for “caustic-ish” look
            color += direct * 0.25;
        }
        else
        {
            // Reflection & normal PBR shading
            float reflectWeight = metallic;
            if(roughness < 0.001) reflectWeight = 1.0; // mirror
            vec3 reflection = envColor * reflectWeight;

            color = direct + reflection * 0.3;

            // Some ambient if not mirror
            if(roughness > 0.0)
            {
                vec3 ambient = vec3(0.2, 0.25, 0.3) * diffuse * 0.5;
                color += ambient;
            }
        }

        //---------------------------------------------------
        // Gamma correction
        color = pow(color, vec3(0.4545)); // ~1/2.2
        fragColor = vec4(color, 1.0);
    }
    else
    {
        // No hit -> background from the cube map
        vec3 bgCol = texture(iChannel0, rd).rgb;
        bgCol = pow(bgCol, vec3(0.4545));
        fragColor = vec4(bgCol, 1.0);
    }
}
